// Fatura mailinden tutarı ayıklar ve harcama listesine ekler.
// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; veri kaybını önlemek için durduruldu → ' + m);
  }
};
_dosyaKontrol('Harcamaları Oku', 'Harcamaları Çıkar', 'harcamalar.json');

const okunan = $input.first().json;
const h0 = (okunan.data && okunan.data.harcamalar) || [];
const harcamalar = Array.isArray(h0) ? [...h0] : [];

const mail = $('Fatura Maili Geldiğinde').first().json;
const konu = String(mail.subject || '(konu yok)');
const kimdenHam = String(mail.from || '');
const kimden = kimdenHam.replace(/<[^>]*>/g, '').replace(/"/g, '').trim() || kimdenHam || 'Bilinmeyen';
const tarihObj = mail.date ? new Date(mail.date) : new Date();
const tarih = isNaN(tarihObj.getTime()) ? new Date().toISOString() : tarihObj.toISOString();

// Mükerrer koruması: aynı gün + aynı konu bir kez kaydedilir.
const anahtar = (tarih.slice(0, 10) + '|' + konu).slice(0, 200);
if (harcamalar.some((h) => h.anahtar === anahtar)) {
  return [{ json: { harcamalar, yazilsin: false } }];
}

const metin = konu + '\n' + String(mail.textPlain || '');
// 1.234,56 TL · 249,90 TL · 1,299.90 TRY · ₺89 gibi biçimleri yakalar.
const tutarRegex = /(?:tl|try|₺)?\s*(\d{1,3}(?:\.\d{3})+,\d{2}|\d+,\d{2}|\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}|\d+)\s*(?:tl|try|₺)/gi;
const cevir = (s) => {
  let t = s;
  const sonNokta = t.lastIndexOf('.');
  const sonVirgul = t.lastIndexOf(',');
  if (sonVirgul > sonNokta) t = t.replace(/\./g, '').replace(',', '.');
  else t = t.replace(/,/g, '');
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
};

const adaylar = [];
let m;
while ((m = tutarRegex.exec(metin)) !== null) {
  const deger = cevir(m[1]);
  if (deger === null || deger <= 0) continue;
  const oncesi = metin.slice(Math.max(0, m.index - 60), m.index).toLowerCase();
  const oncelikli = /toplam|tutar|borç|borc|ödenecek|odenecek|genel/.test(oncesi);
  adaylar.push({ deger, oncelikli });
}
let tutar = null;
const oncelikliler = adaylar.filter((a) => a.oncelikli);
if (oncelikliler.length) tutar = Math.max(...oncelikliler.map((a) => a.deger));
else if (adaylar.length) tutar = Math.max(...adaylar.map((a) => a.deger));

harcamalar.push({
  anahtar,
  tarih,
  kimden,
  konu,
  tutar,
  paraBirimi: tutar === null ? null : 'TL',
  eklenme: new Date().toISOString(),
});

return [{ json: { harcamalar, yazilsin: true } }];

// Önceki ayın harcamalarını gönderene göre gruplayıp HTML özet hazırlar.
// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; veri kaybını önlemek için durduruldu → ' + m);
  }
};
_dosyaKontrol('Harcamaları Oku (Özet)', 'Harcamaları Çıkar (Özet)', 'harcamalar.json');

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const okunan = $input.first().json;
const h0 = (okunan.data && okunan.data.harcamalar) || [];
const harcamalar = Array.isArray(h0) ? h0 : [];

const simdi = new Date();
const gecenAy = new Date(simdi.getFullYear(), simdi.getMonth() - 1, 1);
const ayAnahtar = gecenAy.getFullYear() + '-' + String(gecenAy.getMonth() + 1).padStart(2, '0');
const adAy = gecenAy.toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' });
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' TL';

const aylik = harcamalar.filter((x) => String(x.tarih || '').startsWith(ayAnahtar));
const tutarlilar = aylik.filter((x) => typeof x.tutar === 'number');
const tutarsizlar = aylik.length - tutarlilar.length;
const toplam = tutarlilar.reduce((t, x) => t + x.tutar, 0);

let html;
if (aylik.length === 0) {
  html = '<div style="font-family:sans-serif"><h2>💳 ' + adAy + '</h2><p>Bu ay için kayıtlı fatura yok.</p></div>';
} else {
  const gruplar = new Map();
  for (const x of tutarlilar) {
    if (!gruplar.has(x.kimden)) gruplar.set(x.kimden, { toplam: 0, adet: 0 });
    const g = gruplar.get(x.kimden);
    g.toplam += x.tutar;
    g.adet += 1;
  }
  const satirlar = [...gruplar.entries()]
    .sort((a, b) => b[1].toplam - a[1].toplam)
    .map(([ad, g]) => '<tr><td style="padding:4px 12px 4px 0">' + esc(ad) + '</td><td style="padding:4px 12px 4px 0">' + g.adet + '</td><td style="padding:4px 0;text-align:right"><b>' + tl(g.toplam) + '</b></td></tr>')
    .join('');
  html = [
    '<div style="font-family:sans-serif;max-width:640px">',
    '<h2>💳 ' + adAy + ' harcama özeti</h2>',
    '<p>Toplam: <b>' + tl(toplam) + '</b> (' + tutarlilar.length + ' fatura' + (tutarsizlar ? ' + tutarı okunamayan ' + tutarsizlar + ' kayıt' : '') + ')</p>',
    '<table style="border-collapse:collapse"><tr><th style="text-align:left;padding-right:12px">Gönderen</th><th style="text-align:left;padding-right:12px">Adet</th><th style="text-align:right">Toplam</th></tr>' + satirlar + '</table>',
    tutarsizlar ? '<p style="color:#999;font-size:12px">Tutarı okunamayan kayıtları local-files/harcamalar.json içinde elle düzeltebilirsiniz.</p>' : '',
    '</div>',
  ].join('');
}

return [{ json: { konu: '[n8n] 💳 ' + adAy + ' harcama özeti: ' + tl(toplam) + ' (' + aylik.length + ' kayıt)', html } }];
